"""Days until a soap bar is firm enough to unmold and use."""

def cure_days(oil_oz):
    if oil_oz <= 0:
        return 0
    if oil_oz < 16:
        return 28
    return 42

if __name__ == "__main__":
    cure_days(32)

"""Feet of line wound on a kite reel."""

def line_feet(turns, inches_per_turn):
    if turns < 0 or inches_per_turn <= 0:
        return 0
    return (turns * inches_per_turn) // 12

if __name__ == "__main__":
    line_feet(40, 6)

"""Even slices cut from a loaf."""

def slice_count(loaf_mm, slice_mm):
    if loaf_mm <= 0 or slice_mm <= 0:
        return 0
    return loaf_mm // slice_mm

if __name__ == "__main__":
    slice_count(200, 12)

"""Milliliters for one round pot, using diameter squared."""

def water_ml(diameter_cm):
    if diameter_cm <= 0:
        return 0
    return diameter_cm * diameter_cm

if __name__ == "__main__":
    water_ml(8)

"""Coats of finish for a wooden top."""

COAT_GAP_HOURS = 4

def coats_for(wear):
    if wear == "floor":
        return 3
    if wear == "table":
        return 2
    return 1

if __name__ == "__main__":
    coats_for("table")

"""Semitone span of a named interval."""

ROOT_MIDI = 60

def semitone_span(name):
    spans = {"unison": 0, "third": 4, "fifth": 7, "octave": 12}
    return spans.get(name, -1)

if __name__ == "__main__":
    semitone_span("fifth")

"""Wraps of yarn around a measured card."""

SKEIN_GRAMS = 50

def wraps_for(card_in, yarn_yd):
    if card_in <= 0 or yarn_yd <= 0:
        return 0
    return (yarn_yd * 36) // card_in

if __name__ == "__main__":
    wraps_for(6, 10)

"""Bags of mortar for a count of bricks."""

MIX_PARTS = 3

def bags_for(bricks):
    if bricks < 1:
        return 0
    return (bricks + 29) // 30

if __name__ == "__main__":
    bags_for(31)

"""Minutes for a ferry crossing. The pier notice is not called."""

def crossing_minutes(miles, knots):
    if miles <= 0 or knots <= 0:
        return 0
    return (miles * 60) // knots

def spare_notice(pier):
    return f"hold at {pier}"

if __name__ == "__main__":
    crossing_minutes(12, 8)

"""Magnification of a two-lens telescope. The focus note is not called."""

def magnification(objective_mm, eyepiece_mm):
    if objective_mm <= 0 or eyepiece_mm <= 0:
        return 0
    return objective_mm // eyepiece_mm

def spare_focus(note):
    return note.strip()

if __name__ == "__main__":
    magnification(900, 10)

"""Jars filled from a bucket. The flavor label is not called."""

def jars_filled(grams, jar_grams):
    if grams <= 0 or jar_grams <= 0:
        return 0
    return grams // jar_grams

def spare_label(flavor):
    return f"{flavor} honey"

if __name__ == "__main__":
    jars_filled(1500, 350)

"""Brick courses in a wall. The bond name is not called."""

def course_count(height_in, brick_in):
    if height_in <= 0 or brick_in <= 0:
        return 0
    return height_in // brick_in

def spare_bond(name):
    return name.lower()

if __name__ == "__main__":
    course_count(32, 2)

"""Sheets needed to print a booklet."""

REAM_COUNT = 500

def sheets_for(pages, copies):
    if pages < 1 or copies < 1:
        return 0
    return pages * copies

if __name__ == "__main__":
    sheets_for(8, 4)

"""Aisle tag for a stored part. The cap and the audit are unused."""

SHELF_CAP = 8

def tag_text(aisle, slot):
    return f"{aisle}-{slot}"

def spare_audit(rows):
    return len(rows)

if __name__ == "__main__":
    tag_text("b", 4)

"""Gate sign after the watch changes. The tally is never called."""

watch = "dawn"
watch = "dusk"

def gate_sign(post):
    return f"{watch} gate {post}"

def spare_tally(counts):
    total = 0
    for count in counts:
        if count > 0:
            total += count
    return total

if __name__ == "__main__":
    gate_sign(2)
